fields.InputDefinition:
{
  "goal": "Assume you are already logged in at http://localhost:4200. Using the application switcher dropdown next to the logo (NOT the Ctrl+K search box), open the Communication app, then open its Message Logs section. Open the Filter control (funnel icon) and apply a Status filter such as 'Failed' (or 'Sent'/'Pending'), and/or type a term in the 'Search messages, providers, recipients...' box. Success = the log table RESPONDS — rows narrow to matches OR a clear 'No logs found' empty state appears. Then clear the filter/search and confirm the fuller list returns. Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away.",
  "startUrl": "http://localhost:4200/app/communication",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "Applying a Status filter and/or a search term changes the log table (rows narrow OR a no-results empty state appears)",
    "Clearing the filter and search restores the fuller list",
    "No error messages, blank screens, or crash pages"
  ]
}
